SELECT COUNT(*) AS rent_listings
FROM nlq.listings
WHERE rent_price_per_week IS NOT NULL;

SELECT MAX(agreed_price) AS highest_sale_price
FROM nlq.my_deals
WHERE my_role = 'seller' AND status = 'completed';

SELECT COUNT(*) AS reviews_with_comment
FROM nlq.reviews
WHERE comment IS NOT NULL;

select count(*) as conversations_without_reply
from nlq.conversations
where first_seller_reply_at is null;

SELECT ROUND(AVG(EXTRACT(EPOCH FROM (resolved_at - filed_at))/86400)::numeric, 2) AS avg_days_to_resolve
FROM nlq.reports
WHERE status = 'resolved';

SELECT COUNT(*) AS listings_no_photos
FROM nlq.listings_all
WHERE photo_count = 0;

SELECT COUNT(*) AS requests_waiting_for_response
FROM nlq.deals d
WHERE d.status = 'requested';
